#!/usr/bin/env python3
"""make.fun: The Passport Page of a Country That Isn't There.

Writes the invented passport spread of the Republic of Meridia
(a seafaring island nation) to /output/entry.png.

The spread was drawn with Pillow during development: a data page
with a portrait and machine-readable strip, and a visas page with
arrival and departure stamps from the neighbouring countries of
Sarn, Veyne and Kestrel, plus a seafarer endorsement that reveals
what kind of place Meridia is. Every stamp is dated after the
passport's issue date, 02 JUN 2025, so the travel history agrees
with the document. The finished picture is embedded
below as base64 so the program is stdlib-only and runs in the
grading sandbox, which has no third-party packages.

Deterministic, no network. Output is 1024x1024 PNG, under 1 MiB.
"""
import base64
import os

# The finished spread, base64-encoded PNG (1024x1024, 175314 bytes).
# Meridia: a seafaring island nation; holder Elena Mara Voss, seafarer.
IMAGE_B64 = ""


def main():
    os.makedirs("/output", exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open("/output/entry.png", "wb") as f:
        f.write(data)
    os.chmod("/output/entry.png", 0o644)
    print("saved /output/entry.png", len(data), "bytes")


if __name__ == "__main__":
    main()
